function Materials.normalize(name)
    if not name then return "" end
    local s = string.lower(tostring(name))
    s = string.gsub(s, "<col=[^>]+>", "")
    s = string.gsub(s, "</col>", "")
    s = string.gsub(s, "^%s+", "")
